-- aria:return-stock-officer's return_stock_items grid gets a revised column
-- set: Batch No / Packing Month / SKU Name / Stock Type / Box / PC / Remarks,
-- replacing Qty/Good Stock Qty/Expiry Stock Qty on the VISIBLE table (columns
-- kept on return_stock_officer_item per V312 -- not deleted). Stock Type is
-- a 2-option select: Old Stock / New Stock. M10.ReturnStockIn only.
UPDATE page_version pv
JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"entity":"GatePass","dataSources":[{"id":"returnStockQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:return-stock-officer&size=200"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"ReturnStockOfficer","dataSource":"returnStockQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":[{"field":"gpNumber","label":""},{"field":"vehicleNo"}],"fillLookupEntity":"GatePass","fillLookupField":"gp_number","filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"}],"priorityOverrideField":"priority_override"}]},{"kind":"Section","title":"Vehicle Details","fields":[{"kind":"FormField","type":"text","name":"currentUserId","defaultValue":"{{user.username}}","hidden":true},{"kind":"FormField","type":"select","name":"gpNumber","label":"GP Number","required":true,"placeholder":"Select Gate Pass","freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","valueField":"gp_number","labelField":"gp_number","spec":{"type":"entity","entity":"GatePass","select":["id","gp_number","vehicle_no","flow_variant_code","loading_type","workflow_instance_id"],"filter":{"field":"flow_variant_code","op":"eq","value":"M10.ReturnStockIn"},"sort":[{"field":"gp_number","dir":"desc"}]}},"onChangeFill":{"vehicleNo":"vehicle_no","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"text","name":"vehicleNo","label":"Vehicle Number","disabled":true},{"kind":"FormField","name":"priority_override","type":"text","label":"Priority Override","readOnly":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Vehicle Movement Type","disabled":true}]},{"kind":"Section","title":"Return Stock Details","subtitle":"Batch / Packing Month / SKU / Stock Type / Box / PC -- captured after First Weighment, before QC Approval.","fields":[{"kind":"RepeatingGroup","name":"return_stock_items","label":"Batch / Packing Month / SKU / Stock Type / Box / PC / Remarks","minRows":1,"defaultRows":1,"columns":[{"name":"batch_no","label":"Batch No","type":"text","required":true,"width":"1fr","plainBackground":true},{"name":"packing_month","label":"Packing Month","type":"text","width":"0.9fr","plainBackground":true},{"name":"sku_name","label":"SKU Name","type":"text","required":true,"width":"1.4fr","plainBackground":true},{"name":"stock_type","label":"Stock Type","type":"select","required":true,"width":"0.9fr","plainBackground":true,"options":["Old Stock","New Stock"]},{"name":"box","label":"Box","type":"number","width":"0.6fr","plainBackground":true},{"name":"pc","label":"PC","type":"number","width":"0.6fr","plainBackground":true},{"name":"remarks","label":"Remarks","type":"text","width":"1.2fr","plainBackground":true}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add More","action":"repeatingGroup.addRow","color":"secondary"}]},{"kind":"WorkflowActionButton","label":"Submit Return Stock Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","color":"primary","visibleWhen":"#form.gpNumber != null && #form.gpNumber != ''''"}]}]}'
WHERE pd.code = 'aria:return-stock-officer' AND pv.status = 'PUBLISHED';
